const input = $input.first().json.body || $input.first().json;

// Safe fallback unique id generator using timestamp + random integer 
// that bypasses all n8n node sandbox library security policies
const fallbackId = 'lesson_' + Date.now() + '_' + Math.floor(Math.random() * 1000);

// Safely map incoming fields or default to a structural string format
const lessonId = input.lesson_id || fallbackId;

const context = {
  lesson_id:  lessonId,
  user_id:    input.user_id,
  subject:    input.subject,
  grade:      input.grade,
  topic:      input.topic,
  duration:   input.duration || '45 minutes',
  objectives: input.objectives || `Understand ${input.topic}`,
  language:   input.language || 'English',
  difficulty: input.difficulty || 'Medium',

  systemRole: `You are a senior curriculum designer with 20 years of experience creating educational materials for ${input.subject} at ${input.grade} level.`,
  outputRule: 'CRITICAL OUTPUT RULE: Your entire response must be a single valid JSON object. Start with { and end with }. No markdown fences. No code blocks. No explanation text.',
  languageInstruction: input.language === 'English' ? 'Write entirely in English.' : `Write entirely in ${input.language}. All content must be in ${input.language}.`,
  difficultyInstruction: 'Use grade-appropriate vocabulary. Balance theory and application.'
};

return [{ json: context }];

