parameters.jsCode:
const geminiResponse = $input.first().json;
const context = $('Build Context').first().json;

function robustParse(text) {
  if (!text) throw new Error('Empty input text received.');
  let t = text.trim();

  t = t.replace(/^```json\s*/i, '').replace(/\s*```$/i, '');
  t = t.replace(/^```\s*/i, '').replace(/\s*```$/i, '');

  const start = t.indexOf('{');
  const end   = t.lastIndexOf('}');
  if (start === -1 || end === -1) throw new Error('Master JSON structure truncated or invalid.');
  t = t.slice(start, end + 1);

  // Clean newlines inside string tokens breaking JSON parsing syntax rules
  t = t.replace(/,\s*}/g, '}')
       .replace(/,\s*]/g, ']')
       .replace(/\r?\n|\r/g, ' ')
       .replace(/\t/g, ' ');

  return JSON.parse(t);
}

let masterKit;
try {
  const rawText = geminiResponse?.candidates?.[0]?.content?.parts?.[0]?.text || '';
  masterKit = robustParse(rawText);
} catch(e) {
  throw new Error('MASTER_KIT_PARSE_FAILED: ' + e.message);
}

return [{
  json: {
    lesson_id:  context.lesson_id,
    user_id:    context.user_id,
    lessonPlan: masterKit.lessonPlan || {},
    worksheet:  masterKit.worksheet  || {},
    quiz:       masterKit.quiz       || {},
    rubric:     masterKit.rubric     || {},
    answerKey:  masterKit.answerKey  || {}
  }
}];
